'use client';

import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { Cursor } from './Cursor';
import { RouteTransition } from './RouteTransition';

const navItems = [
  { label: 'Work', href: '/work' },
  { label: 'About', href: '/about' },
  { label: 'Contact', href: '/contact' },
];

export function AppShell({ children, heroTone = 'dark' }: { children: React.ReactNode; heroTone?: 'dark' | 'light' }) {
  const pathname = usePathname();

  return (
    <div className="min-h-screen bg-[#0a0a0a] text-[#f2eee6]">
      <Cursor />
      <RouteTransition />

      <header className="relative z-30 flex items-start justify-between px-4 pt-4 sm:px-6 lg:px-7">
        <Link href="/" className="brand-pill">
          <span className="font-display text-[2rem] leading-none tracking-[-0.08em] font-black uppercase">VARGA</span>
          <span className="font-serif italic text-[1.2rem] leading-none tracking-[-0.04em] ml-2">ines</span>
        </Link>

        <nav
          className={[
            'ml-4 mt-0 flex items-center rounded-full border px-3 py-2 shadow-soft backdrop-blur-[2px]',
            heroTone === 'light' ? 'border-black/10 bg-[rgba(255,255,255,0.22)]' : 'border-white/10 bg-[rgba(22,22,22,0.40)]',
          ].join(' ')}
        >
          {navItems.map((item) => {
            const active = pathname === item.href || (item.href === '/work' && pathname.startsWith('/work'));

            return (
              <Link
                key={item.href}
                href={item.href}
                className={[
                  'relative px-3 py-1 text-[15px] font-medium transition-opacity',
                  active ? 'text-[#f6f2ea]' : 'text-[#f6f2ea]/90',
                ].join(' ')}
                data-cursor-label={item.label}
              >
                <span className="relative z-10">{item.label}</span>
                {active && <span className="absolute inset-x-1 -bottom-1 h-[1px] bg-[#f2eee6]" />}
              </Link>
            );
          })}
        </nav>

        <div className="availability-pill">
          <span className="h-2.5 w-2.5 rounded-full bg-[#ea1f1a] shadow-[0_0_0_2px_rgba(234,31,26,0.15)]" />
          <span className="font-mono text-[10px] uppercase tracking-[0.14em]">Available — Oct 2026</span>
        </div>
      </header>

      <main>{children}</main>

      <footer className="relative z-20 border-t border-[#e8261a] bg-[#0a0a0a] px-4 pb-8 pt-5 sm:px-6 lg:px-7">
        <div className="relative before:absolute before:left-0 before:right-0 before:top-0 before:h-[3px] before:bg-[#e8261a] before:content-['']" />

        <div className="flex flex-col gap-8 pt-6 lg:flex-row lg:items-start lg:justify-between lg:gap-8">
          <div className="min-w-[180px]">
            <div className="mb-6 space-y-3 text-[15px]">
              <Link href="/work" className="block text-[#f5f1ea]" data-cursor-label="Work">Work</Link>
              <Link href="/about" className="block text-[#f5f1ea]" data-cursor-label="About">About</Link>
              <Link href="/contact" className="block text-[#f5f1ea]" data-cursor-label="Contact">Contact</Link>
            </div>

            <div className="space-y-2 text-[12px] uppercase tracking-[0.08em] text-[#f5f1ea]/75">
              <div className="font-mono">Based in</div>
              <div className="font-mono">Lisbon — PT</div>
              <div className="font-mono">New York — US</div>
            </div>
          </div>

          <div className="flex min-w-[180px] flex-col gap-3 text-[17px] text-[#f5f1ea]">
            <div className="font-mono text-[11px] uppercase tracking-[0.18em] text-[#f5f1ea]/75">Social</div>
            <div>Instagram</div>
            <div>Vimeo</div>
            <div>LinkedIn</div>
          </div>

          <div className="flex min-w-[220px] flex-col gap-3 text-[17px] text-[#f5f1ea]">
            <div className="font-mono text-[11px] uppercase tracking-[0.18em] text-[#f5f1ea]/75">Contact</div>
            <div>hello@inesvarga.studio</div>
            <div>+351 912 000 000</div>
          </div>
        </div>

        <div className="mt-8 text-center text-[clamp(5rem,17vw,24rem)] font-display font-black uppercase leading-[0.8] tracking-[-0.08em] text-[#f2eee6]">
          VARGA
        </div>

        <div className="flex justify-end pr-2">
          <button
            className="flex items-center gap-2 rounded-full border border-[#f2eee6] bg-[#f2eee6] px-4 py-2 text-[12px] text-[#0a0a0a] shadow-soft"
            data-cursor-label="Framer"
          >
            <span className="inline-flex h-6 w-6 items-center justify-center rounded-full border border-[#0a0a0a] text-[10px]">↗</span>
            Made in Framer
          </button>
        </div>
      </footer>
    </div>
  );
}
