'use client';

import { usePathname } from 'next/navigation';
import { useEffect, useRef, useState } from 'react';

export function RouteTransition() {
  const pathname = usePathname();
  const [isVisible, setIsVisible] = useState(false);
  const [direction, setDirection] = useState<'forward' | 'reverse'>('forward');
  const lastPathRef = useRef(pathname);

  useEffect(() => {
    const previous = lastPathRef.current;
    const isLanding = pathname === '/' || previous === '/';
    setDirection(isLanding ? 'reverse' : 'forward');
    setIsVisible(true);

    const timeout = window.setTimeout(() => setIsVisible(false), 1100);
    lastPathRef.current = pathname;

    return () => window.clearTimeout(timeout);
  }, [pathname]);

  return (
    <div
      className={['route-transition', isVisible ? 'is-visible' : ''].join(' ')}
      data-direction={direction}
      aria-hidden="true"
    >
      <div className="route-transition__scrim" />
      <div className="route-transition__bar" />
      <div className="route-transition__panel" />
      <div className="route-transition__wordmark">VARGA</div>
    </div>
  );
}
